package com.koratalyoum.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity {
 final int BG=0xff080d17,PANEL=0xff141e2d,SOFT=0xff1c2a3b,LINE=0xff283649,GREEN=0xff31e6a0,WHITE=0xfff7fafc,MUTED=0xff96a7b9,RED=0xffff6575;
 String tab="المباريات",api="";int day=0;LinearLayout page,nav,container;JSONArray cache=new JSONArray();boolean loading=false;
 int[] leagues={307,39,140,135,78,61,2,3,848,17,4,203,262,94,88};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(0);api=getPreferences(0).getString("key","");draw();if(!api.isEmpty())fetch();}
 int dp(float x){return (int)(getResources().getDisplayMetrics().density*x+.5f);}
 GradientDrawable shape(int color,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 LinearLayout vertical(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);v.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return v;}
 LinearLayout horizontal(){LinearLayout v=new LinearLayout(this);v.setOrientation(0);v.setGravity(Gravity.CENTER_VERTICAL);v.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return v;}
 TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));return t;}
 void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
 void add(LinearLayout p,View v){p.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 void space(LinearLayout p,int h){View v=new View(this);p.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
 TextView pill(String title,boolean active){TextView t=text(title,13,active?BG:WHITE,true);t.setGravity(Gravity.CENTER);pad(t,15,10,15,10);t.setBackground(shape(active?GREEN:SOFT,20,active?0:LINE));return t;}
 void draw(){
 LinearLayout screen=vertical();screen.setBackgroundColor(BG);setContentView(screen);
 LinearLayout header=horizontal();pad(header,20,23,20,14);LinearLayout heading=vertical();TextView logo=text("كــورة اليــوم  ⚽",25,WHITE,true);add(heading,logo);space(heading,3);add(heading,text("كل مباراة، كل لحظة",12,MUTED,false));header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));
 TextView live=pill("● LIVE",true);header.addView(live);add(screen,header);
 View divider=new View(this);divider.setBackgroundColor(LINE);screen.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));
 ScrollView sc=new ScrollView(this);sc.setFillViewport(true);container=vertical();pad(container,16,16,16,20);sc.addView(container);screen.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 nav=horizontal();nav.setBackgroundColor(PANEL);pad(nav,5,10,5,10);for(String name:new String[]{"المباريات","مباشر","الأهلي","البطولات","الإعدادات"}){String ico=name.equals("المباريات")?"⚽":name.equals("مباشر")?"🔴":name.equals("الأهلي")?"💚":name.equals("البطولات")?"🏆":"⚙";LinearLayout item=vertical();item.setGravity(Gravity.CENTER);TextView a=text(ico,20,WHITE,false),b=text(name,11,tab.equals(name)?GREEN:MUTED,tab.equals(name));a.setGravity(Gravity.CENTER);b.setGravity(Gravity.CENTER);add(item,a);space(item,3);add(item,b);nav.addView(item,new LinearLayout.LayoutParams(0,dp(58),1));item.setOnClickListener(v->{tab=name;draw();if(!api.isEmpty()&&cache.length()==0)fetch();});}add(screen,nav);render();}
 String date(){Calendar c=Calendar.getInstance(TimeZone.getTimeZone("Asia/Riyadh"));c.add(Calendar.DATE,day);SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setTimeZone(TimeZone.getTimeZone("Asia/Riyadh"));return f.format(c.getTime());}
 void render(){container.removeAllViews();if(tab.equals("الإعدادات")){settings();return;}
 if(tab.equals("المباريات")){TextView title=text("جدول المباريات",24,WHITE,true);add(container,title);space(container,5);add(container,text("نتائج ومواعيد أهم البطولات",13,MUTED,false));space(container,18);
 LinearLayout dates=horizontal();String[] labels={"أمس","اليوم","غدًا"};int[] values={-1,0,1};for(int i=0;i<3;i++){final int d=values[i];TextView x=pill(labels[i],day==d);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),0,dp(3),0);dates.addView(x,lp);x.setOnClickListener(v->{day=d;cache=new JSONArray();render();fetch();});}add(container,dates);space(container,18);}
 else if(tab.equals("مباشر")){add(container,text("🔴  مباريات مباشرة",23,WHITE,true));space(container,5);add(container,text("تابع المباريات لحظة بلحظة",13,MUTED,false));space(container,18);}
 else if(tab.equals("الأهلي")){LinearLayout hero=vertical();pad(hero,20,22,20,22);hero.setBackground(shape(0xff104b3b,22,0xff287d5b));add(hero,text("💚  النادي الأهلي السعودي",23,WHITE,true));space(hero,9);add(hero,text("قلعة الكؤوس  •  مباريات ونتائج",13,0xffbaf5db,false));add(container,hero);space(container,20);}
 else {add(container,text("🏆  البطولات الكبرى",23,WHITE,true));space(container,5);add(container,text("السعودي • الإنجليزي • الإسباني • الأوروبي",13,MUTED,false));space(container,18);}
 if(api.isEmpty()){empty("أدخل مفتاح API-Football من الإعدادات لعرض المباريات الحقيقية.");return;}
 if(loading){empty("جاري تحديث النتائج…");return;}
 int shown=0;String previous="";
 for(int i=0;i<cache.length();i++){JSONObject g=cache.optJSONObject(i);if(g==null)continue;JSONObject l=g.optJSONObject("league"),teams=g.optJSONObject("teams"),fix=g.optJSONObject("fixture"),goals=g.optJSONObject("goals");if(l==null||teams==null||fix==null)continue;
 int id=l.optInt("id");boolean allowed=false;for(int k:leagues)if(k==id)allowed=true;if(!allowed)continue;
 JSONObject h=teams.optJSONObject("home"),a=teams.optJSONObject("away");if(h==null||a==null)continue;String hn=h.optString("name"),an=a.optString("name");boolean ahli=id==307&&(hn.toLowerCase(Locale.ROOT).contains("ahli")||an.toLowerCase(Locale.ROOT).contains("ahli")||hn.contains("الأهلي")||an.contains("الأهلي"));
 if(tab.equals("الأهلي")&&!ahli)continue;
 JSONObject st=fix.optJSONObject("status");String status=st==null?"":st.optString("short");boolean live=Arrays.asList("1H","2H","HT","ET","P","BT","INT").contains(status);if(tab.equals("مباشر")&&!live)continue;
 String league=l.optString("name");if(!league.equals(previous)){if(shown>0)space(container,12);LinearLayout lh=horizontal();TextView ln=text("🏆  "+league,16,WHITE,true);lh.addView(ln,new LinearLayout.LayoutParams(0,-2,1));TextView country=text(l.optString("country"),12,MUTED,false);lh.addView(country);add(container,lh);space(container,12);previous=league;}
 match(g,h,a,goals,status,live);shown++;
 }
 if(shown==0)empty("لا توجد مباريات متاحة لهذا القسم في التاريخ المحدد.");
 if(shown>0){space(container,10);TextView refresh=pill("↻  تحديث النتائج",false);add(container,refresh);refresh.setOnClickListener(v->fetch());}}
 void empty(String msg){LinearLayout e=vertical();e.setGravity(Gravity.CENTER);pad(e,20,48,20,48);e.setBackground(shape(PANEL,20,LINE));TextView ball=text("⚽",36,WHITE,false);ball.setGravity(Gravity.CENTER);add(e,ball);space(e,12);TextView m=text(msg,15,MUTED,false);m.setGravity(Gravity.CENTER);add(e,m);add(container,e);}
 void match(JSONObject g,JSONObject h,JSONObject a,JSONObject goals,String status,boolean live){
 LinearLayout card=vertical();pad(card,14,14,14,14);card.setBackground(shape(PANEL,19,LINE));LinearLayout.LayoutParams outer=new LinearLayout.LayoutParams(-1,-2);outer.bottomMargin=dp(10);container.addView(card,outer);
 LinearLayout top=horizontal();TextView statusText=text(live?"● مباشر":status.equals("FT")?"انتهت":status.equals("NS")?"قادمة":status,12,live?RED:MUTED,true);top.addView(statusText,new LinearLayout.LayoutParams(0,-2,1));JSONObject fix=g.optJSONObject("fixture");String date=fix==null?"":fix.optString("date");String tm=date.length()>15?date.substring(11,16):"";top.addView(text(tm+"  KSA",12,MUTED,false));add(card,top);space(card,12);
 LinearLayout teams=horizontal();team(teams,h);LinearLayout center=vertical();center.setGravity(Gravity.CENTER);String hs=goals==null||goals.isNull("home")?"–":goals.optString("home"),as=goals==null||goals.isNull("away")?"–":goals.optString("away");TextView score=text(hs+"  :  "+as,25,WHITE,true);score.setGravity(Gravity.CENTER);add(center,score);TextView subtitle=text(live?"LIVE":status.equals("FT")?"FULL TIME":"VS",10,live?GREEN:MUTED,true);subtitle.setGravity(Gravity.CENTER);add(center,subtitle);teams.addView(center,new LinearLayout.LayoutParams(dp(98),-2));team(teams,a);add(card,teams);
 }
 void team(LinearLayout row,JSONObject team){LinearLayout col=vertical();col.setGravity(Gravity.CENTER);ImageView logo=new ImageView(this);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);col.addView(logo,new LinearLayout.LayoutParams(dp(45),dp(45)));loadLogo(team.optString("logo"),logo);space(col,7);TextView name=text(team.optString("name"),12,WHITE,true);name.setGravity(Gravity.CENTER);name.setMaxLines(2);add(col,name);row.addView(col,new LinearLayout.LayoutParams(0,-2,1));}
 void loadLogo(String url,ImageView target){if(!url.startsWith("https://"))return;new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(6000);c.setReadTimeout(6000);Bitmap bitmap=BitmapFactory.decodeStream(c.getInputStream());if(bitmap!=null)runOnUiThread(()->target.setImageBitmap(bitmap));}catch(Exception ignored){}}).start();}
 void settings(){add(container,text("⚙  إعدادات التطبيق",23,WHITE,true));space(container,14);add(container,text("مصدر النتائج: API-Football",16,WHITE,true));space(container,8);add(container,text("المفتاح محفوظ محليًا على جهازك. لا تشاركه مع الآخرين.",13,MUTED,false));space(container,12);EditText input=new EditText(this);input.setSingleLine(true);input.setText(api);input.setTextColor(WHITE);input.setHintTextColor(MUTED);input.setHint("API Key");pad(input,12,10,12,10);input.setBackground(shape(PANEL,12,LINE));add(container,input);space(container,12);TextView save=pill("حفظ المفتاح",true);add(container,save);save.setOnClickListener(v->{api=input.getText().toString().trim();getPreferences(0).edit().putString("key",api).apply();tab="المباريات";draw();fetch();});space(container,20);add(container,text("كورة اليوم  •  نسخة 2.0",12,MUTED,false));}
 void fetch(){if(api.isEmpty())return;loading=true;render();String d=date();new Thread(()->{try{URL u=new URL("https://v3.football.api-sports.io/fixtures?date="+d+"&timezone=Asia%2FRiyadh");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestProperty("x-apisports-key",api);c.setConnectTimeout(12000);c.setReadTimeout(15000);int http=c.getResponseCode();if(http!=200)throw new Exception("HTTP "+http);ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)b.write(bytes,0,n);}JSONObject json=new JSONObject(b.toString("UTF-8"));JSONArray result=json.optJSONArray("response");if(result==null)throw new Exception("API response");runOnUiThread(()->{cache=result;loading=false;render();});}catch(Exception ex){runOnUiThread(()->{loading=false;container.removeAllViews();empty("تعذر تحميل النتائج. تحقق من الإنترنت أو مفتاح API.");});}}).start();}
}